        self.transitions = {} # char -> State
        self.is_final = False
        self.id = -1

    def __hash__(self):
        # Only valid for hashing after children are hashed and IDs are assigned
        # Wait, since it's a DAG, we can hash them bottom-up.
        pass

def build_dawg(words):
    root = State()
    for word in words:
        curr = root
        for char in word:
            if char not in curr.transitions:
                curr.transitions[char] = State()
            curr = curr.transitions[char]
        curr.is_final = True

    # Now minimize bottom-up
    # Since it's a tree, we can just do a post-order traversal
    state_map = {}
    next_id = 0

    def post_order(state):
        nonlocal next_id
        # First process children
        for char in sorted(state.transitions.keys()):
            state.transitions[char] = post_order(state.transitions[char])

        # Now create a signature for this state
        trans_sig = tuple(sorted((char, target.id) for char, target in state.transitions.items()))
        sig = (state.is_final, trans_sig)

        if sig in state_map:
            return state_map[sig]
        else:
            state.id = next_id
            next_id += 1
            state_map[sig] = state
