    # Bottom-up substitution
    def solve(state):
        if state.id in cache:
            return cache[state.id]

        # Collect terms
        terms = []
        if state.is_final:
            terms.append("")

        for char, target in state.transitions.items():
            sub = solve(target)
            if sub == "":
                terms.append(char)
            else:
                terms.append(char + sub)

