            res = ""
        elif len(terms) == 1:
            res = terms[0]
        else:
            # We need to factor out common prefixes or suffixes
            # For now, just join with |
            res = "(?:" + "|".join(terms) + ")"

        cache[state.id] = res
        return res

    return solve(state)

