def build_char_class(chars):
    special = {'$', '^', '\\', '[', ']', '-'}
    def escape(c):
        return '\\' + c if c in special else c

    chars = sorted(set(chars))
    runs = []
    i = 0
    while i < len(chars):
        j = i
        while j + 1 < len(chars) and ord(chars[j+1]) == ord(chars[j]) + 1:
            j += 1
        runs.append(chars[i:j+1])
        i = j + 1

    res = "["
    for r in runs:
        if len(r) >= 3:
            res += escape(r[0]) + "-" + escape(r[-1])
        else:
            for c in r:
                res += escape(c)
    res += "]"
    return res

